\begin{aligned}
    f(X = x, Y = y) &= f(X = x) \cdot f(Y = y) && \text{In the prior X and Y are independent} \\
    &= \frac{1}{\sqrt{2 \cdot 4 \cdot \pi}}\cdot e ^{-\frac{(x-3)^2}{2 \cdot 4}} \cdot\frac{1}{\sqrt{2 \cdot 4 \cdot \pi}}\cdot e ^{-\frac{(y-3)^2}{2 \cdot 4}} && \text{Using the PDF equation for normals} \\
    &= K_1 \cdot e ^{-\frac{(x-3)^2 + (y-3)^2}{8}} && \text{All constants are put into } K_1
\end{aligned}

\begin{aligned}
    f(D = d \mid X = x, Y = y)
      &= \frac{1}{\sqrt{2 \cdot 1 \cdot \pi}}\cdot e ^{-\frac{\big(d-\sqrt{x^2 + y^2}\big)^2}{2}}  && \text{Normal PDF where } \mu = \sqrt{x^2 + y^2} \\
      &= K_2\cdot e ^{-\frac{\big(d-\sqrt{x^2 + y^2}\big)^2}{2}}  && \text{All constants are put into } K_2
\end{aligned}

\begin{aligned}
    \frac{f(D = 1 \mid X = 1, Y = 1)}{f(D = 2 \mid X = 1, Y = 1)}
      &= \frac{ K_2\cdot e ^{-\frac{\big(1-\sqrt{1^2 + 1^2}\big)^2}{2}} }{ K_2\cdot e ^{-\frac{\big(2-\sqrt{1^2 + 1^2}\big)^2}{2}} }  && \text{Substituting into the conditional PDF of D}\\
      &= \frac{ e^0 }{ e^{-1/2} }\approx 1.65 && \text{Notice how the }K_2\text{ cancel out}
\end{aligned}

\begin{aligned}
f&(X = x, Y = y \mid D = 4) \\
    &= \frac{f(D = 4\mid X = x, Y = y) \cdot f(X = x, Y = y)}{f(D = 4)} && \text{Bayes using densities}\\
    &= \frac{K_1 \cdot e^{-\frac{(4 - \sqrt{x^2 + y^2})^2}{2}} \cdot K_2 \cdot e^{-\frac{(x - 3)^2 + (y - 3)^2}{8}}}{f(D = 4)} && \text{Substitute}\\
    &= \frac{K_1 \cdot K_2}{ f(D = 4)} \cdot e ^{-\Big[\frac{(4 - \sqrt{x^2 + y^2})^2}{2} + \frac{(x - 3)^2 + (y - 3)^2}{8}\Big]} && \text{\(f(D=4)\) is a constant w.r.t. \((x,y)\)}\\
    &= K_3 \cdot e ^{-\Big[\frac{(4 - \sqrt{x^2 + y^2})^2}{2} + \frac{(x - 3)^2 + (y - 3)^2}{8}\Big]} && \text{\(K_3\) is a new constant}
\end{aligned}
